#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Fitur Undang Teman Dapat Koin
# Jalankan di root repo:  bash pasang-undang-teman.sh
# Lalu: git add -A && git commit -m "fitur undang teman" && git push  (GitHub Actions akan build APK)
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
[ -f "$D/DailyCoinActivity.kt" ] || { echo "❌ Jalankan di root repo Hayu-android"; exit 1; }
T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"
BK="$HOME/.hayu-backup-invite-$(date +%H%M%S)"
N=0
for f in $(cd "$T/new" && find . -type f | sed 's#^\./##'); do
  [ -f "$f" ] && { mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; }
  mkdir -p "$(dirname "$f")"
  cp "$T/new/$f" "$f"
  echo "  dipasang $f"
  N=$((N+1))
done
grep -q "InviteFriendsActivity" app/src/main/AndroidManifest.xml || { echo "❌ Manifest belum terdaftar"; exit 1; }
rm -rf "$T"
echo "✅ $N file dipasang. Backup: $BK"
echo "Lanjut: git add -A && git commit -m 'fitur undang teman' && git push"
